add_filter( 'woocommerce_cart_shipping_method_full_label', 'perfectpixel_hide_shipping_rate_label', 10, 2 );

function perfectpixel_hide_shipping_rate_label( $label, $method ) {
	if ( (float) $method->get_cost() <= 0 ) {
		return $label;
	}
	$pos = strpos( $label, ':' );
	return false === $pos ? $label : ltrim( substr( $label, $pos + 1 ) );
}
